3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11	
12		"github.com/go-git/go-git/v6"
13		"github.com/go-git/go-git/v6/plumbing"
14	
15		"github.com/entireio/cli/cmd/entire/cli/internal/flock"
16	)
17	
18	// Push-discovery queue file names, kept in the git common dir so every worktree
19	// sharing the object store enqueues into one queue. The git-refs backend cannot
20	// push every local checkpoint ref at pre-push time (reads fetch refs too, and
21	// deleting them after push would hurt local workflows), so each write records
22	// the ref it touched here and pre-push drains + batch-pushes exactly those.
23	const (
24		pushQueueFileName = "entire-checkpoint-push-queue.jsonl"
25		pushQueueLockName = "entire-checkpoint-push-queue.lock"
26	)
27	
28	// pushQueueEntry is one JSONL record: a checkpoint ref awaiting push.
29	type pushQueueEntry struct {
30		Ref string `json:"ref"`
31	}
32	
33	// PushQueue is a flock-protected JSONL list of checkpoint refs awaiting push,
34	// stored in the git common dir. Entries are removed only after a confirmed push
35	// (Remove), so an interrupted or failed push leaves them for the next pre-push.
36	// Duplicates are tolerated on disk and collapsed by Drain.
37	type PushQueue struct {
38		dir string
39	}
40	
41	// NewPushQueue returns the push queue rooted at gitCommonDir.
42	func NewPushQueue(gitCommonDir string) *PushQueue {
43		return &PushQueue{dir: gitCommonDir}
44	}
45	
46	// PushQueueForRepo resolves the git common dir for repo and returns its queue.
47	func PushQueueForRepo(ctx context.Context, repo *git.Repository) (*PushQueue, error) {
48		dir, err := resolveGitCommonDir(ctx, repo)
49		if err != nil {
50			return nil, err
51		}
52		return NewPushQueue(dir), nil
53	}
54	
55	func (q *PushQueue) queuePath() string { return filepath.Join(q.dir, pushQueueFileName) }
56	func (q *PushQueue) lockPath() string  { return filepath.Join(q.dir, pushQueueLockName) }
57	
58	// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
59	// present (or already pushed): Drain collapses duplicates and the batch push is
60	// idempotent. Enqueue takes the lock so concurrent writers never interleave a
61	// partial line.
62	func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
63		release, err := flock.Acquire(q.lockPath())
64		if err != nil {
65			return fmt.Errorf("lock push queue: %w", err)
66		}
67		defer release()
68	
69		line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
70		if err != nil {
71			return fmt.Errorf("encode push queue entry: %w", err)
72		}
73		f, err := os.OpenFile(q.queuePath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
74		if err != nil {
75			return fmt.Errorf("open push queue: %w", err)
76		}
77		defer f.Close()
78		if _, err := f.Write(append(line, '\n')); err != nil {
79			return fmt.Errorf("append push queue entry: %w", err)
80		}
81		return nil
82	}
83	
84	// Drain returns the de-duplicated refs currently queued, in first-seen order. It
85	// does NOT remove them; call Remove after a confirmed push so a failed push
86	// retries next time. A missing queue file yields no refs.
87	//
88	// It compacts the file in place: when the on-disk queue held redundant lines
89	// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
90	// it to the de-duplicated set. Enqueue only ever appends, so without this the
91	// file would grow unboundedly between the Removes that are otherwise the sole
92	// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
93	// checkpoint ref but never pushes).
94	func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
95		release, err := flock.Acquire(q.lockPath())
96		if err != nil {
97			return nil, fmt.Errorf("lock push queue: %w", err)
98		}
99		defer release()
100	
101		refs, rawLines, err := q.readLocked()
102		if err != nil {
103			return nil, err
104		}
105		if rawLines > len(refs) {
106			if err := q.rewriteLocked(refs); err != nil {
107				return nil, err
108			}
109		}
110		return refs, nil
111	}
112	
113	// Remove deletes the given refs from the queue, preserving any entries appended
114	// after a Drain (e.g. a write that landed during the push). Called after a
115	// confirmed push.
116	func (q *PushQueue) Remove(refs []plumbing.ReferenceName) error {
117		if len(refs) == 0 {
118			return nil
119		}
120		release, err := flock.Acquire(q.lockPath())
121		if err != nil {
122			return fmt.Errorf("lock push queue: %w", err)
123		}
124		defer release()
125	
126		current, _, err := q.readLocked()
127		if err != nil {
128			return err
129		}
130		removed := make(map[string]struct{}, len(refs))
131		for _, r := range refs {
132			removed[r.String()] = struct{}{}
133		}
134		kept := make([]plumbing.ReferenceName, 0, len(current))
135		for _, r := range current {
136			if _, drop := removed[r.String()]; drop {
137				continue
138			}
139			kept = append(kept, r)
140		}
141		return q.rewriteLocked(kept)
142	}
143	
144	// rewriteLocked replaces the queue file with exactly refs (de-duplicated, one
145	// line each), or removes the file when refs is empty so a clean repo has no
146	// stray queue. The caller must hold the lock. The write is atomic (temp file +
147	// rename) so a concurrent reader never sees a half-written queue.
148	func (q *PushQueue) rewriteLocked(refs []plumbing.ReferenceName) error {
